import{_ as t,o as i,c as s,a5 as r}from"./chunks/framework.CsGesDJn.js";const f=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"feature/profile/3-3-2-update-profile/report3_spec.md","filePath":"feature/profile/3-3-2-update-profile/report3_spec.md"}'),a={name:"feature/profile/3-3-2-update-profile/report3_spec.md"};function o(n,e,l,d,p,u){return i(),s("div",null,[...e[0]||(e[0]=[r("<p><strong>3.3.2 Update Profile</strong></p><p><strong>Function Trigger</strong></p><p>Begins when a signed-in user saves edits to their profile fields on /profile, or selects a new avatar image in the avatar upload dialog.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: Any authenticated user (role USER); a user updates only their own profile.</li><li><strong>Purpose</strong>: Let the user keep their personal information accurate — display name, phone number, professional title, bio, portfolio links, working language, timezone, notification preferences — and refresh their avatar.</li><li><strong>Interface</strong>: The Profile screen at /profile in edit mode: editable full-name field, phone field, job-title field, working-language field, bio textarea, a repeatable portfolio-URL list, a timezone selector, and a Save button. Saving submits a full update (PUT semantics). The avatar is changed separately through the avatar upload dialog. Cancel restores every field (including all four listed above) to its last-saved value.</li><li><strong>Data Processing</strong>: The system loads the user record, writes the submitted full name, phone, professional title, bio, portfolio URLs, and working language directly onto the record, merges the submitted timezone and notification preferences into the stored preferences data (only submitted fields are overwritten), persists the record, and returns the updated profile. Avatar upload is handled independently: the file is validated, stored, the previous avatar file removed when one exists, and the new reference saved.</li><li>Known gap: notificationPreferences is wired end-to-end on the backend, but the Profile screen has no UI for it yet.</li></ul><p><strong>Screen Layout</strong></p><p>Figure — Profile Screen (/profile, edit mode):</p><ul><li>Center: full-name input (required), phone input, job-title input, working-language input, bio textarea, repeatable portfolio URL inputs (add/remove), timezone selector. Email and avatar are shown but not editable from this form.</li><li>Buttons: Save (primary); Cancel — discards changes and restores last-saved values.</li><li>Footer: none.</li></ul><p>Figure — Avatar Upload Dialog:</p><ul><li>Center: image file selector and preview.</li><li>Buttons: Upload — submits the image; Cancel — closes without changes.</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: fullName; an image file for the avatar upload action.</li><li><strong>Input optional</strong>: phone, professionalTitle, bio, portfolioUrls, workingLanguage, timezone, notificationPreferences.</li><li><strong>System data</strong>: users (fullName, phone, professionalTitle, bio, portfolioUrls, workingLanguage, preferences JSON, avatarUrl).</li><li><strong>Output</strong>: userId, email, fullName, avatarUrl, phone, role, workspaceId, professionalTitle, bio, portfolioUrls, workingLanguage, timezone, notificationPreferences, createdAt; avatar upload returns the new avatarUrl.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-19</strong>: The update request carries no email or avatar field, so neither can be submitted through this action; changing email is out of scope.</li><li>Only fields actually submitted (non-empty) overwrite the stored preferences data.</li><li><strong>BR-20</strong>: Avatar upload — file required, content type must start with image/, max 5 MB.</li><li>When a new avatar uploads successfully, the previous avatar file is deleted.</li><li>Removing the avatar results in the default initials avatar, not an error.</li><li>Avatar upload is independent of the profile field update; one failing does not block the other.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>fullName empty or blank → Display: <strong>MSG02</strong>.</li><li>Preferences data cannot be serialized (rare) → Display: <strong>MSG02</strong>.</li><li>Avatar upload: no file provided → Display: <strong>MSG27</strong>; wrong content type → Display: <strong>MSG28</strong>; file exceeds 5 MB → Display: <strong>MSG29</strong>; file cannot be read → Display: <strong>MSG38</strong>.</li><li>Missing, expired, or invalid access token → Display: <strong>MSG22</strong>.</li><li>User record no longer exists → Display: <strong>MSG38</strong>.</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ol><li>The user edits the form on /profile and clicks Save.</li><li>The application submits the changed profile fields.</li><li>The system loads the user record and writes the submitted full name and phone number.</li><li>The system merges the submitted timezone and notification preferences into the stored preferences data, overwriting only submitted fields.</li><li>The system persists the record and returns the complete updated profile.</li><li>The application shows a success confirmation and refreshes the profile without a page reload; toast <strong>MSG26</strong>.</li><li>Separately, the user selects an image in the avatar upload dialog and submits it.</li><li>The system validates the file, stores it, deletes the previous avatar file when one exists, saves the new reference, and returns the new avatar value; toast <strong>MSG30</strong>.</li></ol></li><li><p><strong>Abnormal Cases</strong></p><ul><li>3.a1: The user record no longer exists, the system displays <strong>MSG38</strong>. 3.a2: The user is signed out and returned to /login.</li><li>3.b1: fullName submitted empty or blank, the system displays <strong>MSG02</strong>. 3.b2: The user re-enters a full name and saves again.</li><li>4.a1: The preferences data cannot be serialized, the system displays <strong>MSG02</strong>. 4.a2: The user retries Save.</li><li>8.a1: No file is provided, the system displays <strong>MSG27</strong>. 8.a2: The user selects a file and submits again.</li><li>8.b1: The file&#39;s content type is not an image, the system displays <strong>MSG28</strong>. 8.b2: The user selects an image file and submits again.</li><li>8.c1: The file exceeds 5 MB, the system displays <strong>MSG29</strong>. 8.c2: The user selects a smaller image and submits again.</li><li>8.d1: The file cannot be read during upload, the system displays <strong>MSG38</strong>. 8.d2: The user retries the upload.</li><li>8.e1: The avatar is removed instead of replaced, the default initials avatar is shown, no error.</li><li>N.a1: Missing, expired, or invalid access token at any step, the system displays <strong>MSG22</strong>. N.a2: The user signs in again at /login (3.2.2).</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>fullName, phone, professionalTitle, bio, portfolioUrls, workingLanguage, timezone, and notificationPreferences hold the submitted values; fields left out keep their previous values.</li><li>The avatar reference reflects the most recent successful upload, or the default initials avatar when removed.</li><li>The avatar is stored independently of the profile field update.</li></ul>",16)])])}const h=t(a,[["render",o]]);export{f as __pageData,h as default};
